import type {ComponentType} from 'react';

import type {IconData} from '@gravity-ui/uikit';

export type TrackerSelectItemValueBase = {
    id: string;
    display?: string;
};

export type TrackerSelectItem<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = {
    id: string;
    display: string;
    category?: TrackerSelectItemValueBase;
    name?: string;
    value?: Value;
    system?: boolean;
    meta?: string;
    tags?: string[];
    required?: boolean;
    pinned?: boolean;
    type?: string;
};

export type TrackerSelectItems<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = Record<string, TrackerSelectItem<Value>>;

export type TrackerSelectGroup<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = {
    id: string;
    keyPrefix?: string;
    name?: string;
    icon?: IconData;
    type?: 'named' | 'data';
    topmost?: boolean;
    collapsible?: boolean;
    expand?: boolean;
    tag?: string;
    items: TrackerSelectItems<Value>;
};

export type TrackerSelectItemContentProps<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = {
    item: TrackerSelectItem<Value>;
};

export type TrackerSelectItemActions<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = ComponentType<TrackerSelectItemContentProps<Value>>;
